```tsx
import { useId } from "react";
import "./ChipFilter.css";

export interface ChipOption {
  value: string;
  label: string;
}

export interface ChipFilterProps {
  label: string;
  options: readonly ChipOption[];
  selected: readonly string[];
  onToggle: (value: string) => void;
}

export function ChipFilter({ label, options, selected, onToggle }: ChipFilterProps) {
  const labelId = useId();

  return (
    <div role="group" aria-labelledby={labelId} className="chip-filter">
      <span id={labelId} className="chip-filter__label">
        {label}
      </span>
      <div className="chip-filter__chips">
        {options.map((option) => {
          const isOn = selected.includes(option.value);
          return (
            <button
              key={option.value}
              type="button"
              aria-pressed={isOn}
              onClick={() => onToggle(option.value)}
              className="chip-filter__chip"
            >
              <span className="chip-filter__dot" aria-hidden="true" />
              {option.label}
            </button>
          );
        })}
      </div>
    </div>
  );
}
