.chip-filter {
  display: flex;
  flex-direction: column;
  gap: 0.5em;
  color: var(--ink);
}

.chip-filter__label {
  font-size: clamp(0.8rem, 0.5rem + 0.6vw, 0.95rem);
  color: var(--muted);
}

.chip-filter__chips {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5em;
}

.chip-filter__chip {
  font: inherit;
  font-size: clamp(0.85rem, 0.55rem + 0.7vw, 1rem);
  display: inline-flex;
  align-items: center;
  gap: 0.45em;
  padding: 0.35em 0.9em;
  border: 1px solid var(--muted);
  border-radius: 999px;
  background: transparent;
  color: var(--ink);
  cursor: pointer;
  transition:
    background-color 150ms ease,
    border-color 150ms ease;
}

.chip-filter__chip:hover {
  border-color: var(--ink);
}

.chip-filter__chip[aria-pressed="true"] {
  border-color: var(--myelin);
  background: var(--myelin-wash);
}

.chip-filter__dot {
  display: inline-block;
  width: 0.5em;
  height: 0.5em;
  border-radius: 999px;
  border: 1px solid currentColor;
  background: transparent;
}

.chip-filter__chip[aria-pressed="true"] .chip-filter__dot {
  background: var(--myelin);
  border-color: var(--myelin);
}

:root[data-motion="reduce"] .chip-filter__chip {
  transition: none;
}

@media (prefers-reduced-motion: reduce) {
  .chip-filter__chip {
    transition: none;
  }
}
